            case 1:
                return "\u007C\u00C6\u00DE\u00DE\u00DE\u00C0\u0078\u0000\u0030\u0078\u00CC\u00CC\u00FC\u00CC\u00CC\u0000\u00FC\u0066\u0066\u007C\u0066\u0066\u00FC\u0000\u003C\u0066\u00C0\u00C0\u00C0\u0066\u003C\u0000\u00F8\u006C\u0066\u0066\u0066\u006C\u00F8\u0000\u00FE\u0062\u0068\u0078\u0068\u0062\u00FE\u0000\u00FE\u0062\u0068\u0078\u0068\u0060\u00F0\u0000\u003C\u0066\u00C0\u00C0\u00CE\u0066\u003E\u0000\u00CC\u00CC\u00CC\u00FC\u00CC\u00CC\u00CC\u0000\u0078\u0030\u0030\u0030\u0030\u0030\u0078\u0000\u001E\u000C\u000C\u000C\u00CC\u00CC\u0078\u0000\u00E6\u0066\u006C\u0078\u006C\u0066\u00E6\u0000\u00F0\u0060\u0060\u0060\u0062\u0066\u00FE\u0000\u00C6\u00EE\u00FE\u00FE\u00D6\u00C6\u00C6\u0000\u00C6\u00E6\u00F6\u00DE\u00CE\u00C6\u00C6\u0000\u0038\u006C\u00C6\u00C6\u00C6\u006C\u0038\u0000\u00FC\u0066\u0066\u007C\u0060\u0060\u00F0\u0000\u0078\u00CC\u00CC\u00CC\u00DC\u0078\u001C\u0000\u00FC\u0066\u0066\u007C\u006C\u0066\u00E6\u0000\u0078\u00CC\u00E0\u0070\u001C\u00CC\u0078\u0000\u00FC\u00B4\u0030\u0030\u0030\u0030\u0078\u0000\u00CC\u00CC\u00CC\u00CC\u00CC\u00CC\u00FC\u0000\u00CC\u00CC\u00CC\u00CC\u00CC\u0078\u0030\u0000\u00C6\u00C6\u00C6\u00D6\u00FE\u00EE\u00C6\u0000\u00C6\u00C6\u006C\u0038\u0038\u006C\u00C6\u0000\u00CC\u00CC\u00CC\u0078\u0030\u0030\u0078\u0000\u00FE\u00C6\u008C\u0018\u0032\u0066\u00FE\u0000\u0078\u0060\u0060\u0060\u0060\u0060\u0078\u0000\u00C0\u0060\u0030\u0018\u000C\u0006\u0002\u0000\u0078\u0018\u0018\u0018\u0018\u0018\u0078\u0000\u0010\u0038\u006C\u00C6\u0000\u0000\u0000\u0000\u0000\u0000\u0000\u0000\u0000\u0000\u0000\u00FF\u0030\u0030\u0018\u0000\u0000\u0000\u0000\u0000\u0000\u0000\u0078\u000C\u007C\u00CC\u0076\u0000\u00E0\u0060\u0060\u007C\u0066\u0066\u00DC\u0000\u0000\u0000\u0078\u00CC\u00C0\u00CC\u0078\u0000\u001C\u000C\u000C\u007C\u00CC\u00CC\u0076\u0000\u0000\u0000\u0078\u00CC\u00FC\u00C0\u0078\u0000\u0038\u006C\u0060\u00F0\u0060\u0060\u00F0\u0000\u0000\u0000\u0076\u00CC\u00CC\u007C\u000C\u00F8\u00E0\u0060\u006C\u0076\u0066\u0066\u00E6\u0000\u0030\u0000\u0070\u0030\u0030\u0030\u0078\u0000\u000C\u0000\u000C\u000C\u000C\u00CC\u00CC\u0078\u00E0\u0060\u0066\u006C\u0078\u006C\u00E6\u0000\u0070\u0030\u0030\u0030\u0030\u0030\u0078\u0000\u0000\u0000\u00CC\u00FE\u00FE\u00D6\u00C6\u0000\u0000\u0000\u00F8\u00CC\u00CC\u00CC\u00CC\u0000\u0000\u0000\u0078\u00CC\u00CC\u00CC\u0078\u0000\u0000\u0000\u00DC\u0066\u0066\u007C\u0060\u00F0\u0000\u0000\u0076\u00CC\u00CC\u007C\u000C\u001E\u0000\u0000\u00DC\u0076\u0066\u0060\u00F0\u0000\u0000\u0000\u007C\u00C0\u0078\u000C\u00F8\u0000\u0010\u0030\u007C\u0030\u0030\u0034\u0018\u0000\u0000\u0000\u00CC\u00CC\u00CC\u00CC\u0076\u0000\u0000\u0000\u00CC\u00CC\u00CC\u0078\u0030\u0000\u0000\u0000\u00C6\u00D6\u00FE\u00FE\u006C\u0000\u0000\u0000\u00C6\u006C\u0038\u006C\u00C6\u0000\u0000\u0000\u00CC\u00CC\u00CC\u007C\u000C\u00F8\u0000\u0000\u00FC\u0098\u0030\u0064\u00FC\u0000\u001C\u0030\u0030\u00E0\u0030\u0030\u001C\u0000\u0018\u0018\u0018\u0000\u0018\u0018\u0018\u0000\u00E0\u0030\u0030\u001C\u0030\u0030\u00E0\u0000\u0076\u00DC\u0000\u0000\u0000\u0000\u0000\u0000\u0000\u0010\u0038\u006C\u00C6\u00C6\u00FE\u0000";
            case 2:
                return "\u0078\u00CC\u00C0\u00CC\u0078\u0018\u000C\u0078\u0000\u00CC\u0000\u00CC\u00CC\u00CC\u007E\u0000\u001C\u0000\u0078\u00CC\u00FC\u00C0\u0078\u0000\u007E\u00C3\u003C\u0006\u003E\u0066\u003F\u0000\u00CC\u0000\u0078\u000C\u007C\u00CC\u007E\u0000\u00E0\u0000\u0078\u000C\u007C\u00CC\u007E\u0000\u0030\u0030\u0078\u000C\u007C\u00CC\u007E\u0000\u0000\u0000\u0078\u00C0\u00C0\u0078\u000C\u0038\u007E\u00C3\u003C\u0066\u007E\u0060\u003C\u0000\u00CC\u0000\u0078\u00CC\u00FC\u00C0\u0078\u0000\u00E0\u0000\u0078\u00CC\u00FC\u00C0\u0078\u0000\u00CC\u0000\u0070\u0030\u0030\u0030\u0078\u0000\u007C\u00C6\u0038\u0018\u0018\u0018\u003C\u0000\u00E0\u0000\u0070\u0030\u0030\u0030\u0078\u0000\u00C6\u0038\u006C\u00C6\u00FE\u00C6\u00C6\u0000\u0030\u0030\u0000\u0078\u00CC\u00FC\u00CC\u0000\u001C\u0000\u00FC\u0060\u0078\u0060\u00FC\u0000\u0000\u0000\u007F\u000C\u007F\u00CC\u007F\u0000\u003E\u006C\u00CC\u00FE\u00CC\u00CC\u00CE\u0000\u0078\u00CC\u0000\u0078\u00CC\u00CC\u0078\u0000\u0000\u00CC\u0000\u0078\u00CC\u00CC\u0078\u0000\u0000\u00E0\u0000\u0078\u00CC\u00CC\u0078\u0000\u0078\u00CC\u0000\u00CC\u00CC\u00CC\u007E\u0000\u0000\u00E0\u0000\u00CC\u00CC\u00CC\u007E\u0000\u0000\u00CC\u0000\u00CC\u00CC\u007C\u000C\u00F8\u00C3\u0018\u003C\u0066\u0066\u003C\u0018\u0000\u00CC\u0000\u00CC\u00CC\u00CC\u00CC\u0078\u0000\u0018\u0018\u007E\u00C0\u00C0\u007E\u0018\u0018\u0038\u006C\u0064\u00F0\u0060\u00E6\u00FC\u0000\u00CC\u00CC\u0078\u00FC\u0030\u00FC\u0030\u0030\u00F8\u00CC\u00CC\u00FA\u00C6\u00CF\u00C6\u00C7\u000E\u001B\u0018\u003C\u0018\u0018\u00D8\u0070\u001C\u0000\u0078\u000C\u007C\u00CC\u007E\u0000\u0038\u0000\u0070\u0030\u0030\u0030\u0078\u0000\u0000\u001C\u0000\u0078\u00CC\u00CC\u0078\u0000\u0000\u001C\u0000\u00CC\u00CC\u00CC\u007E\u0000\u0000\u00F8\u0000\u00F8\u00CC\u00CC\u00CC\u0000\u00FC\u0000\u00CC\u00EC\u00FC\u00DC\u00CC\u0000\u003C\u006C\u006C\u003E\u0000\u007E\u0000\u0000\u0038\u006C\u006C\u0038\u0000\u007C\u0000\u0000\u0030\u0000\u0030\u0060\u00C0\u00CC\u0078\u0000\u0000\u